  -- gtk4
  { ns = "gtk4-layer-shell",          no_anim = true },
}

for _, r in ipairs(layer_rules) do
  local rule = { match = { namespace = r.ns } }
  if r.xray ~= nil        then rule.xray = r.xray end
  if r.no_anim then rule.no_anim = true end
  if r.blur then rule.blur = true end
  if r.blur_popups then rule.blur_popups = true end
  if r.ignore_alpha then rule.ignore_alpha = r.ignore_alpha end
  if r.animation then rule.animation = r.animation end
  if r.order then rule.order = r.order end
  -- ponytail: xray = false is set explicitly for quickshell:popup
  if r.xray == false then rule.xray = false end
  hl.layer_rule(rule)
end
